//! Integration tests of the virtual folder "Everything" (`ui.md`):
//! `list_everything` reads whole threads from `thread` instead of merging
//! every folder (`list_threads_in`), and must list the same threads, in the
//! same order, shown in the same folder with the same counters, page after
//! page.
//!
//! The mailbox is generated by `seed` (deterministic): several thousand
//! threads spread over every workflow folder, with flags, attachments,
//! replies and unread mail.

use nm_api::{ThreadFilter, ThreadSort, ThreadSummary};
use nm_store::Store;
use nm_store::seed::{SeedOptions, seed};

/// A seeded store and the ids of every folder.
fn store() -> (Store, Vec<i64>) {
    let mut store = Store::open_in_memory().unwrap();
    seed(&mut store, &SeedOptions { threads: 1500, seed: 7, now: 1_750_000_000 }).unwrap();
    let folders = store.list_folders().unwrap().iter().map(|f| f.id).collect();
    (store, folders)
}

/// Every page of a list, read `page` threads at a time.
fn all_pages(mut next: impl FnMut(Option<&str>) -> (Vec<ThreadSummary>, Option<String>)) -> Vec<ThreadSummary> {
    let mut out = Vec::new();
    let mut cursor: Option<String> = None;
    loop {
        let (items, c) = next(cursor.as_deref());
        out.extend(items);
        match c {
            Some(c) => cursor = Some(c),
            None => return out,
        }
    }
}

/// What a list row shows, compared between the two ways of listing.
fn rows(items: &[ThreadSummary]) -> Vec<(i64, i64, i64, i64, i64, i64)> {
    items.iter().map(|t| (t.id, t.folder_id, t.date_last_received, t.date_last_modified, t.message_count, t.unread_count)).collect()
}

/// The filters compared. Not `seen`: see
/// `unread_in_everything_looks_at_the_whole_thread`.
fn filters() -> Vec<ThreadFilter> {
    vec![
        ThreadFilter::default(),
        ThreadFilter { flagged: Some(true), ..Default::default() },
        ThreadFilter { flagged: Some(false), ..Default::default() },
        ThreadFilter { attachments: Some(true), ..Default::default() },
        ThreadFilter { answered: Some(true), ..Default::default() },
        ThreadFilter { conversation: Some(true), ..Default::default() },
        ThreadFilter { from: vec!["@gmail.com".into()], ..Default::default() },
        ThreadFilter { not_from: vec!["@gmail.com".into()], ..Default::default() },
        ThreadFilter { to: vec!["alex".into()], ..Default::default() },
        ThreadFilter { contains: Some("facture".into()), ..Default::default() },
        ThreadFilter { after: Some(1_740_000_000), before: Some(1_745_000_000), ..Default::default() },
    ]
}

#[test]
fn everything_lists_what_every_folder_lists_page_after_page() {
    let (store, folders) = store();
    let accounts: Vec<i64> = {
        let mut a: Vec<i64> = store.list_folders().unwrap().iter().map(|f| f.account_id).collect();
        a.dedup();
        a
    };
    for filter in filters() {
        for sort in [ThreadSort::Received, ThreadSort::Modified] {
            let merged = all_pages(|c| store.list_threads_in(&folders, c, 37, sort, &filter).unwrap());
            let everything = all_pages(|c| store.list_everything(None, c, 37, sort, &filter).unwrap());
            assert!(!merged.is_empty() || filter != ThreadFilter::default());
            assert_eq!(rows(&everything), rows(&merged), "{filter:?} {sort:?}");
            // The scope of one account gives the same, the seed having one.
            let one = all_pages(|c| store.list_everything(Some(accounts[0]), c, 37, sort, &filter).unwrap());
            assert_eq!(rows(&one), rows(&merged), "account {filter:?} {sort:?}");
        }
    }
    // Another account sees nothing of this one.
    let (none, next) = store.list_everything(Some(9999), None, 50, ThreadSort::Received, &ThreadFilter::default()).unwrap();
    assert!(none.is_empty() && next.is_none());
}

#[test]
fn unread_in_everything_looks_at_the_whole_thread() {
    // A thread with an unread mail in one folder, but whose latest mail is
    // read and in another folder (the Inbox mail, then the user's reply in
    // Sent, say). Listed folder by folder, the thread was shown in the
    // folder of its latest mail, where nothing is unread, and its unread
    // row was skipped as not the latest: it vanished from "unread".
    let (mut store, _) = store();
    // A thread of the seed in two folders or more, made read everywhere,
    // then one mail of an older folder made unread again (the counters are
    // updated as `refresh_thread` would).
    let (thread, older): (i64, i64) = store
        .conn()
        .query_row(
            "SELECT tf.thread_id, tf.folder_id FROM thread_folder tf
              WHERE EXISTS (SELECT 1 FROM thread_folder o WHERE o.thread_id = tf.thread_id
                             AND o.date_last_received > tf.date_last_received)
              LIMIT 1",
            [],
            |r| Ok((r.get(0)?, r.get(1)?)),
        )
        .expect("the seed has threads in several folders");
    store.set_thread_seen(thread, true, nm_core::Source::Cli).unwrap();
    store
        .conn()
        .execute_batch(&format!(
            "UPDATE message SET is_seen = 0 WHERE id = (SELECT id FROM message WHERE thread_id = {thread} AND folder_id = {older} LIMIT 1);
             UPDATE thread_folder SET unread_count = 1 WHERE thread_id = {thread} AND folder_id = {older};
             UPDATE thread SET unread_count = 1 WHERE id = {thread};"
        ))
        .unwrap();
    let unread = ThreadFilter { seen: Some(false), ..Default::default() };
    let everything = all_pages(|c| store.list_everything(None, c, 100, ThreadSort::Received, &unread).unwrap());
    assert!(everything.iter().any(|t| t.id == thread));
    // And "read" leaves it out: it has an unread mail.
    let read = ThreadFilter { seen: Some(true), ..Default::default() };
    let everything = all_pages(|c| store.list_everything(None, c, 100, ThreadSort::Received, &read).unwrap());
    assert!(!everything.iter().any(|t| t.id == thread));
}

#[test]
fn a_cursor_of_everything_continues_where_the_page_stopped() {
    let (store, _) = store();
    let filter = ThreadFilter::default();
    let (first, cursor) = store.list_everything(None, None, 10, ThreadSort::Received, &filter).unwrap();
    let (second, _) = store.list_everything(None, cursor.as_deref(), 10, ThreadSort::Received, &filter).unwrap();
    let (both, _) = store.list_everything(None, None, 20, ThreadSort::Received, &filter).unwrap();
    assert_eq!(rows(&[first, second].concat()), rows(&both));
    // A malformed cursor is refused.
    assert!(store.list_everything(None, Some("x"), 10, ThreadSort::Received, &filter).is_err());
}
